1	export type Item = { type: string };
2	export type Step = { op: string; items?: Item[] };
3	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
4	
5	export type StepResult = { premium: number };
6	export type ScenarioResult = { results: StepResult[] };
7	
8	const BASE_PREMIUMS: Record<string, number> = {
9	  sword: 100,
10	  amulet: 60,
11	  staff: 80,
12	  potion: 40,
13	  rune: 25,
14	};
15	
16	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
17	const PROCESSING_FEE = 5;
18	
19	const policyBasePremium = (items: Item[] = []): number =>
20	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
21	
22	const quotePremium = (items?: Item[]): number => {
23	  const basePremium = policyBasePremium(items);
24	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
25	  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
26	};
27	
28	export const runScenario = (scenario: Scenario): ScenarioResult => ({
29	  results: scenario.steps.map((step) => ({
30	    premium: quotePremium(step.items),
31	  })),
32	});
